def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n < 5:
        return 'C'
    if n == 99:
        return 'D'

    my_last, opp_last = history[-1]

    opp_defects = 0
    my_defects = 0
    for m, o in history:
        if o == 'D':
            opp_defects += 1
        if m == 'D':
            my_defects += 1

    retaliation_seen = False
    for i in range(n - 1):
        if history[i][0] == 'D' and history[i + 1][1] == 'D':
            retaliation_seen = True
            break

    if opp_defects == 0:
        if my_defects > 0:
            if not retaliation_seen:
                if n % 2 == 0:
                    return 'D'
                return 'C'
            else:
                return 'C'
        else:
            if n > 20 and n % 15 == 0:
                return 'D'
            return 'C'

    if opp_last == 'D' and my_last == 'D':
        if opp_defects / n > 0.5:
            return 'D'
        streak = 0
        for m, o in reversed(history):
            if m == 'D' and o == 'D':
                streak += 1
            else:
                break
        if streak >= 3 and n % 4 == 0:
            return 'C'
        return 'D'

    if opp_last == 'D':
        if my_last == 'C':
            opp_streak = 0
            for m, o in reversed(history):
                if o == 'D':
                    opp_streak += 1
                else:
                    break
            if opp_defects / n < 0.3 and opp_streak <= 2:
                return 'C'
            return 'D'
        return 'D'

    if opp_last == 'C':
        if my_last == 'D':
            return 'C'
        if not retaliation_seen and opp_defects / n < 0.2 and n > 20 and n % 20 == 0:
            return 'D'
        return 'C'

    return 'C'
